-- SQL commands to upload UAX post-sale data
-- Generated: 2026-04-29 11:41:52

CREATE TABLE IF NOT EXISTS auction_sales (
    id SERIAL PRIMARY KEY,
    stock_number VARCHAR(50),
    year INTEGER,
    make VARCHAR(100),
    model VARCHAR(100),
    style VARCHAR(200),
    color VARCHAR(50),
    odometer INTEGER,
    grade DECIMAL(2,1),
    sale_date DATE,
    lane INTEGER,
    price DECIMAL(10,2),
    auction_location VARCHAR(100),
    uploaded_at TIMESTAMP DEFAULT NOW()
);

